import{z as n,x as s,o as t,c as d,q as l,j as r,D as a,d as A,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"迭代轮次的数据策略","description":"","frontmatter":{"title":"迭代轮次的数据策略","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ade-iteration-data-strategy.md","filePath":"llm/ade-iteration-data-strategy.md","lastUpdated":1791063341000}'),D={name:"llm/ade-iteration-data-strategy.md"};function p(C,E,m,F,h,f){const B=s("Mermaid");return t(),d("div",null,[E[2]||(E[2]=l('<h1 id="迭代轮次的数据策略" tabindex="-1">迭代轮次的数据策略 <a class="header-anchor" href="#迭代轮次的数据策略" aria-label="Permalink to &quot;迭代轮次的数据策略&quot;">​</a></h1><div class="epigraph"><p>每一轮训练都移动策略，策略一动，上一轮的数据就开始贬值；迭代不是重复采集，而是对着这一轮的失败，买下一轮的数据。</p><footer>—— 据 Ouyang 等 InstructGPT 2022、Touvron 等 Llama 2 2023 的多轮迭代口径整理</footer></div><p><a href="/llm/ade-safety-helpful-mix">上一课</a>把配比钉成分域下限与帕累托工作点，并留了一句：工作点每轮重估。本课把时间轴拉进来——轮次之间数据怎么组织：采什么、留什么、退役什么。第一课立过资产生命周期的循环，本课写循环每转一圈的具体账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>迭代把两个时间效应摆上桌面。其一是分布贬值：策略每轮移动，旧对子的 \\(y_w \\gt y_l\\) 取自旧策略的支撑，新策略的输出落在新支撑里，旧边界开始对外推负责（<a href="/llm/rm-ood-behavior">分布外的奖励行为</a>的机制），训练侧再叠加离策略的修正负担（<a href="/llm/off-policy-importance-rl">离策略与重要性采样</a>的口径）。其二是定义漂移：指南与政策改版后，旧批次的判断锚过期——数据没坏，测的东西换了。全量重采不可能，全量复用更不行；每轮的账要算清楚：多少预算修已知弱点，多少预算扩新覆盖，旧数据留多少、降多少权。</p><p><span class="marginnote">\\(y_w \\gt y_l\\) 读作「好回答胜过坏回答」：一条偏好数据就是同一个问题下的两个回答，人挑出更好的那个（\\(y_w\\) 是被选中的，\\(y_l\\) 是被拒绝的）。所谓「取自旧策略的支撑」，是说这两个回答都是旧版模型写得出来的——新版模型已经会写出不一样的答案，旧数据就没覆盖到那里了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>轮次策略四件。第一件失败驱动的配额：上一轮的失败（评测门禁的失败域加线上回流）定义下一轮采集的域配额，每条候选样本的信息价值用<a href="/llm/rm-active-collection">主动采集下一批偏好</a>的口径估计；预算分两个口袋记账——修弱点与扩覆盖，只修弱点的轮次序列会让覆盖悄悄停滞。第二件分层保留：提示库是长寿资产（不依赖策略），比较对是耗材（随策略贬值），政策映射随政策版本；三层半衰期不同，账本分开。第三件新旧混锚：新一轮对旧轮的部分提示重标，同提示新旧标签的不一致率直接量化判断锚漂移了多少，顺带把新指南的口径带进旧簇。第四件四元组版本绑定：轮次号、模型版本、指南版本、政策版本写进每批数据卡，让任何一轮的分数都能对上「用哪份定义、哪批分布训的」。</p>',8)),(t(),r(i,null,{default:a(()=>[o(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEPLOY%5B%22%E7%AC%AC%20N%20%E8%BD%AE%E9%83%A8%E7%BD%B2%22%5D%20--%3E%20FAILS%5B%22%E5%A4%B1%E8%B4%A5%E5%9B%9E%E6%B5%81%EF%BC%9A%E8%AF%84%E6%B5%8B%E9%97%A8%E7%A6%81%20%2B%20%E7%BA%BF%E4%B8%8A%22%5D%0A%20%20FAILS%20--%3E%20QUOTA%5B%22%E5%9F%9F%E9%85%8D%E9%A2%9D%EF%BC%9A%E4%BF%AE%E5%BC%B1%E7%82%B9%20%2B%20%E6%89%A9%E8%A6%86%E7%9B%96%22%5D%0A%20%20QUOTA%20--%3E%20COLLECT%5B%22%E9%87%87%E9%9B%86%EF%BC%9A%E6%96%B0%E6%8F%90%E7%A4%BA%20%2B%20%E6%97%A7%E6%8F%90%E7%A4%BA%E9%87%8D%E6%A0%87%22%5D%0A%20%20COLLECT%20--%3E%20ANCHOR%5B%22%E6%96%B0%E6%97%A7%E6%B7%B7%E9%94%9A%EF%BC%9A%E4%B8%8D%E4%B8%80%E8%87%B4%E7%8E%87%20%3D%20%E9%94%9A%E6%BC%82%E7%A7%BB%22%5D%0A%20%20ANCHOR%20--%3E%20MIX%5B%22%E6%B7%B7%E8%AE%AD%EF%BC%9A%E6%97%A7%E5%AF%B9%E9%99%8D%E6%9D%83%20%2F%20%E6%96%B0%E5%AF%B9%E5%8A%A0%E6%9D%83%22%5D%0A%20%20MIX%20--%3E%20NEXT%5B%22%E7%AC%AC%20N%2B1%20%E8%BD%AE%22%5D%0A%20%20NEXT%20--%3E%7C%22%E7%AD%96%E7%95%A5%E7%A7%BB%E5%8A%A8%22%7C%20DEPLOY%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"贬值为什么是机制的必然而不是管理问题：RM 学的是「在策略支撑内分辨好坏」，这个前提随策略移动而松动。旧对子并非清零——它对不变的部分（格式、语言、长期稳定的偏好）仍有解释力，贬值的是与新策略相关的部分，所以降权比丢弃便宜且稳：丢弃等于断言旧分布毫无信息，通常不成立。锚漂移用重标不一致率度量，机制上它同时含两件事：指南改版的口径差与标注流程的随机误差——所以要配上未改版提示的对照组，把两者分开：改了版的提示不一致率高是口径差，没改版的提示不一致率也高，那是流程在抖。",-1)),E[5]||(E[5]=e("p",null,"一轮结束后，三类数据因贬值速度不同而处置各异，这就是分层保留的账本：",-1)),(t(),r(i,null,{default:a(()=>[o(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22%E6%8F%90%E7%A4%BA%E5%BA%93%EF%BC%88%E8%B5%84%E4%BA%A7%EF%BC%89%22%5D%20--%3E%7C%22%E5%87%A0%E4%B9%8E%E4%B8%8D%E8%B4%AC%E5%80%BC%22%7C%20KEEP%5B%22%E5%8E%9F%E6%A0%B7%E4%BF%9D%E7%95%99%EF%BC%8C%E8%B7%A8%E8%BD%AE%E5%A4%8D%E7%94%A8%22%5D%0A%20%20C%5B%22%E6%AF%94%E8%BE%83%E5%AF%B9%EF%BC%88%E8%80%97%E6%9D%90%EF%BC%89%22%5D%20--%3E%7C%22%E9%9A%8F%E7%AD%96%E7%95%A5%E7%A7%BB%E5%8A%A8%E8%B4%AC%E5%80%BC%22%7C%20DOWN%5B%22%E9%99%8D%E6%9D%83%E6%B7%B7%E8%AE%AD%EF%BC%8C%E8%80%8C%E9%9D%9E%E4%B8%A2%E5%BC%83%22%5D%0A%20%20PM%5B%22%E6%94%BF%E7%AD%96%E6%98%A0%E5%B0%84%22%5D%20--%3E%7C%22%E9%9A%8F%E6%8C%87%E5%8D%97%E6%94%B9%E7%89%88%E8%BF%87%E6%9C%9F%22%7C%20REMAP%5B%22%E6%8C%89%E6%96%B0%E6%94%BF%E7%AD%96%E7%89%88%E6%9C%AC%E9%87%8D%E6%98%A0%E5%B0%84%22%5D%0A%20%20KEEP%20--%3E%20NEXT%5B%22%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E8%BD%AE%E8%AE%AD%E7%BB%83%E6%B1%A0%22%5D%0A%20%20DOWN%20--%3E%20NEXT%0A%20%20REMAP%20--%3E%20NEXT%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">「降权」可以想象成调低旧歌单的音量而不是删歌：歌还是那首，只是出现得少。若把旧对子的权重从 1 降到 0.3，模型每看约三遍新数据才回顾一遍旧数据——保留了旧分布里仍有用的信息，又不会被它拖着走。</span></p><p><span class="marginnote">实用的一刀切账法：每轮数据卡上写两行——「本轮为修弱点花多少、为扩覆盖花多少」。三轮之后翻回去看，若扩覆盖一行持续为零，这个模型的边界在这三轮里没有变大过。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>轮次策略不替代质量门：旧数据降权也不豁免入库前的去重与清洗。迭代有过优化的天花板：轮次越多，策略对 RM 缺口的利用越充分（<a href="/llm/rm-overoptimization">RM 过优化与 Goodhart</a> 的曲线），靠堆轮次掩盖数据缺口会把曲线推向陡段。线上反馈的持续回流与模型的持续更新是另一门课的地界，本课只到「轮」为止——轮是工程上有账可查的最小单位。</p><p><span class="marginnote">初学者容易以为训练轮数越多模型越好。实际上 RM 只是真实偏好的代理打分器：轮次一多，模型会专挑打分器的漏洞刷分（比如学会套模板拿高分），真实水平反而下降——这就是 Goodhart 曲线：代理分数还在涨，真实质量已经拐弯。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>策略每轮移动，旧比较对随之贬值；提示是资产，比较对是耗材，政策映射随版本。</li><li>失败驱动配额：修弱点与扩覆盖分开记账，主动采集给信息价值定价。</li><li>新旧混锚：旧提示重标的不一致率量化锚漂移，配未改版对照组分离随机误差。</li><li>四元组版本绑定让每轮分数可追溯；降权比丢弃便宜。</li><li>出处：Ouyang 等 InstructGPT，2022；Touvron 等 Llama 2，2023 的迭代口径，按本课程整理。</li></ul>',7))])}const T=n(D,[["render",p]]);export{_ as __pageData,T as default};
